-- Squashed baseline for the WMNY Shift Swap schema.
--
-- Replaces the original 16 migrations. Those could not build a database from
-- scratch: Prisma orders migrations by the numeric timestamp prefix, so the
-- fifteen hand-named 8-digit directories sorted ahead of the 14-digit
-- 20260401214939_init, init ran last, and the first migration applied failed
-- with 42P01 relation "users" does not exist. See
-- docs/migration-baseline-squash.md.
--
-- Generated by replaying all 16 migrations in dependency order (init first)
-- against an empty Postgres 16, then dumping the resulting schema. Verified
-- to reproduce that schema byte-for-byte on a clean database.
--
-- The last two statements are the partial unique indexes from
-- prisma/partial-indexes.sql. They cannot be expressed in schema.prisma, and
-- without them duplicate proposals return 201 instead of 409.
--
-- DO NOT deploy this without first running, on every live environment:
--   npx prisma migrate resolve --applied 20260720000000_baseline
-- vercel-build runs `prisma migrate deploy && next build`, so deploying it
-- unresolved fails with P3018 / 42710 and blocks every later deploy.

CREATE TYPE public."AgreementStatus" AS ENUM (
    'pending',
    'userA_confirmed',
    'accepted',
    'completed',
    'cancelled',
    'declined',
    'disputed'
);
CREATE TYPE public."ReportStatus" AS ENUM (
    'pending',
    'reviewed',
    'dismissed'
);
CREATE TYPE public."SwapCategory" AS ENUM (
    'work',
    'daysoff',
    'vacation',
    'open_work'
);
CREATE TYPE public."SwapStatus" AS ENUM (
    'open',
    'pending',
    'filled',
    'expired'
);
CREATE TYPE public."UserRole" AS ENUM (
    'operator',
    'depotRep',
    'admin',
    'subAdmin',
    'dispatcher'
);
CREATE TABLE public.announcements (
    id text NOT NULL,
    depot_id text NOT NULL,
    author_id text NOT NULL,
    body character varying(600) NOT NULL,
    pinned boolean DEFAULT false NOT NULL,
    expires_at timestamp(3) without time zone,
    created_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(3) without time zone NOT NULL
);
CREATE TABLE public.audit_logs (
    id text NOT NULL,
    admin_id text NOT NULL,
    action text NOT NULL,
    target_id text,
    target_type text,
    detail text,
    ip text,
    created_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE public.blocks (
    id text NOT NULL,
    blocker_id text NOT NULL,
    blocked_id text NOT NULL,
    created_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE public.depots (
    id text NOT NULL,
    name text NOT NULL,
    code text NOT NULL,
    borough text NOT NULL,
    operator text NOT NULL,
    logo_url text
);
CREATE TABLE public.invite_codes (
    id text NOT NULL,
    code text NOT NULL,
    created_by text NOT NULL,
    used_by text,
    is_valid boolean DEFAULT true NOT NULL,
    created_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE public.messages (
    id text NOT NULL,
    swap_id text,
    from_user_id text NOT NULL,
    to_user_id text NOT NULL,
    text character varying(2000) NOT NULL,
    read boolean DEFAULT false NOT NULL,
    created_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE public.notifications (
    id text NOT NULL,
    user_id text NOT NULL,
    type text NOT NULL,
    title text NOT NULL,
    body text NOT NULL,
    url text,
    read boolean DEFAULT false NOT NULL,
    created_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE public.push_subscriptions (
    id text NOT NULL,
    user_id text NOT NULL,
    endpoint text NOT NULL,
    p256dh text NOT NULL,
    auth text NOT NULL,
    created_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE public.reports (
    id text NOT NULL,
    swap_id text NOT NULL,
    reporter_id text NOT NULL,
    reason text,
    status public."ReportStatus" DEFAULT 'pending'::public."ReportStatus" NOT NULL,
    created_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE public.reputation (
    id text NOT NULL,
    user_id text NOT NULL,
    completed integer DEFAULT 0 NOT NULL,
    cancelled integer DEFAULT 0 NOT NULL,
    "noShow" integer DEFAULT 0 NOT NULL,
    created_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE public.reviews (
    id text NOT NULL,
    swap_id text NOT NULL,
    reviewer_id text NOT NULL,
    reviewed_id text NOT NULL,
    rating integer NOT NULL,
    created_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE public.saved_swaps (
    id text NOT NULL,
    user_id text NOT NULL,
    swap_id text NOT NULL,
    created_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE public.swap_agreements (
    id text NOT NULL,
    swap_id text NOT NULL,
    user_a_id text NOT NULL,
    user_b_id text NOT NULL,
    status public."AgreementStatus" DEFAULT 'pending'::public."AgreementStatus" NOT NULL,
    user_a_note character varying(500),
    user_b_note character varying(500),
    user_a_at timestamp(3) without time zone,
    user_b_at timestamp(3) without time zone,
    completed_at timestamp(3) without time zone,
    created_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(3) without time zone NOT NULL,
    accepted_at timestamp(3) without time zone,
    user_a_happened boolean,
    user_b_happened boolean,
    shift_date date
);
CREATE TABLE public.swaps (
    id text NOT NULL,
    user_id text NOT NULL,
    depot_id text NOT NULL,
    category public."SwapCategory" NOT NULL,
    status public."SwapStatus" DEFAULT 'open'::public."SwapStatus" NOT NULL,
    date date,
    details character varying(500) NOT NULL,
    contact text,
    run text,
    route text,
    start_time text,
    clear_time text,
    swing_start text,
    swing_end text,
    from_day text,
    from_date date,
    to_day text,
    to_date date,
    vacation_have text,
    vacation_want text,
    poster_name text NOT NULL,
    created_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(3) without time zone NOT NULL,
    archived_at timestamp(3) without time zone
);
CREATE TABLE public.users (
    id text NOT NULL,
    email text NOT NULL,
    password_hash text NOT NULL,
    first_name text NOT NULL,
    last_name text NOT NULL,
    depot_id text,
    language text DEFAULT 'en'::text NOT NULL,
    avatar_url text,
    verified boolean DEFAULT false NOT NULL,
    invited_by text,
    created_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(3) without time zone NOT NULL,
    role public."UserRole" DEFAULT 'operator'::public."UserRole" NOT NULL,
    flexible_mode boolean DEFAULT false NOT NULL,
    flexible_since timestamp(3) without time zone,
    email_verify_token text,
    email_verify_expires timestamp(3) without time zone,
    terms_accepted_at timestamp(3) without time zone,
    terms_version text,
    login_attempts integer DEFAULT 0 NOT NULL,
    locked_until timestamp(3) without time zone,
    suspended_until timestamp(3) without time zone,
    last_active_at timestamp(3) without time zone,
    job_title text,
    depot_set_at timestamp(3) without time zone,
    verified_operator boolean DEFAULT false NOT NULL,
    dispatcher_verified boolean DEFAULT false NOT NULL,
    dispatcher_badge text,
    notification_prefs jsonb,
    quiet_end text,
    quiet_start text,
    signup_source text
);
