    ADD CONSTRAINT announcements_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.audit_logs
    ADD CONSTRAINT audit_logs_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.blocks
    ADD CONSTRAINT blocks_blocker_id_blocked_id_key UNIQUE (blocker_id, blocked_id);
ALTER TABLE ONLY public.blocks
    ADD CONSTRAINT blocks_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.depots
    ADD CONSTRAINT depots_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.invite_codes
    ADD CONSTRAINT invite_codes_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.messages
    ADD CONSTRAINT messages_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.notifications
    ADD CONSTRAINT notifications_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.push_subscriptions
    ADD CONSTRAINT push_subscriptions_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.reports
    ADD CONSTRAINT reports_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.reputation
    ADD CONSTRAINT reputation_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.reviews
    ADD CONSTRAINT reviews_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.saved_swaps
    ADD CONSTRAINT saved_swaps_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.swap_agreements
    ADD CONSTRAINT swap_agreements_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.swaps
    ADD CONSTRAINT swaps_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.users
    ADD CONSTRAINT users_pkey PRIMARY KEY (id);
CREATE INDEX audit_logs_admin_id_idx ON public.audit_logs USING btree (admin_id);
CREATE INDEX audit_logs_created_at_idx ON public.audit_logs USING btree (created_at DESC);
CREATE INDEX blocks_blocked_id_idx ON public.blocks USING btree (blocked_id);
CREATE UNIQUE INDEX depots_code_key ON public.depots USING btree (code);
CREATE UNIQUE INDEX invite_codes_code_key ON public.invite_codes USING btree (code);
CREATE UNIQUE INDEX invite_codes_used_by_key ON public.invite_codes USING btree (used_by);
CREATE INDEX messages_from_user_id_to_user_id_created_at_idx ON public.messages USING btree (from_user_id, to_user_id, created_at DESC);
CREATE INDEX messages_swap_id_idx ON public.messages USING btree (swap_id);
CREATE INDEX messages_to_user_id_read_idx ON public.messages USING btree (to_user_id, read);
CREATE INDEX notifications_user_id_created_at_idx ON public.notifications USING btree (user_id, created_at DESC);
CREATE INDEX notifications_user_id_read_idx ON public.notifications USING btree (user_id, read);
CREATE UNIQUE INDEX push_subscriptions_endpoint_key ON public.push_subscriptions USING btree (endpoint);
CREATE UNIQUE INDEX reputation_user_id_key ON public.reputation USING btree (user_id);
CREATE UNIQUE INDEX reviews_swap_id_reviewer_id_key ON public.reviews USING btree (swap_id, reviewer_id);
CREATE INDEX saved_swaps_user_id_idx ON public.saved_swaps USING btree (user_id);
CREATE UNIQUE INDEX saved_swaps_user_id_swap_id_key ON public.saved_swaps USING btree (user_id, swap_id);
CREATE INDEX swap_agreements_status_shift_date_idx ON public.swap_agreements USING btree (status, shift_date);
CREATE UNIQUE INDEX swap_agreements_swap_id_accepted_key ON public.swap_agreements USING btree (swap_id) WHERE (status = ANY (ARRAY['accepted'::public."AgreementStatus", 'userA_confirmed'::public."AgreementStatus"]));
CREATE UNIQUE INDEX swap_agreements_swap_user_pending_key ON public.swap_agreements USING btree (swap_id, user_a_id) WHERE (status = 'pending'::public."AgreementStatus");
CREATE INDEX swaps_archived_at_idx ON public.swaps USING btree (archived_at);
CREATE INDEX swaps_depot_id_status_created_at_idx ON public.swaps USING btree (depot_id, status, created_at DESC);
CREATE INDEX swaps_user_id_created_at_idx ON public.swaps USING btree (user_id, created_at);
CREATE INDEX swaps_user_id_status_idx ON public.swaps USING btree (user_id, status);
CREATE UNIQUE INDEX users_email_key ON public.users USING btree (email);
